using System;using System.IO;using System.Text;using System.Collections.Generic;
// Tower-only monster drops (FG364).
// Source: data/death-tower-items-FG364.dat, generated by local-run/pvf/gen_death_tower_items_fg364.py.
//
// report 2026-10-27: "塔内怪物掉的东西错误了，塔内只会掉一些专属的【塔】无色小晶块之类的道具".
// A tower monster's `.mob` carries two drop blocks:
//     [item] / [common champion drop item]  -> the ordinary table used outside a tower
//     [death tower item]                    -> the table the tower uses
// towerofdeath.dgn / towerofillusion.dgn only carry probabilities and weights
// (`[tower fp cubepiece]`, `[tower limit of stackable item]`, `[tower max clear item num]`,
// and etc/deathtower.etc `[reward item prob] 50 49 100` / `[reward gold weight]` /
// `[reward exp weight]` per floor), never item ids - those live in the monster's
// `[death tower item]` rows (6515 (塔)无色小晶块, 6518 (塔)迅捷药剂, 6519 (塔)圣护药剂,
// 6523 (塔)上级魔力药剂), and many of the death-tower roster carry an EMPTY block (no drop).
// So a tower kill plans only this table: no gold pile, no equipment, no stack/world roll and
// never the ordinary [item] pool that was leaking 1000/1047/1004/3171 into the tower.
class Offline70DeathTowerDropsFG364{
 internal const string Magic="FG364TD1";internal const int MaximumBytes=262144;
 // monster id -> {item, cumulative weight} rows, file order.
 static readonly Dictionary<ushort,uint[][]> Table=new Dictionary<ushort,uint[][]>();
 internal static int Records,Items;
 internal static void Load(string path){
  if(Table.Count!=0)return;byte[] b=File.ReadAllBytes(path);if(b.Length<74||b.Length>MaximumBytes)throw new InvalidDataException("Death tower drop catalog size");
  if(Encoding.ASCII.GetString(b,0,8)!=Magic)throw new InvalidDataException("Death tower drop catalog magic");
  if(Encoding.ASCII.GetString(b,8,64).ToUpperInvariant()!=Offline70QuestCatalogFG.CurrentPvf)throw new InvalidDataException("Death tower drop catalog PVF");
  int count;
  using(BinaryReader r=new BinaryReader(new MemoryStream(b,false),Encoding.ASCII)){
   r.BaseStream.Position=72;count=r.ReadUInt16();if(count<1||count>4096)throw new InvalidDataException("Death tower drop record count");
   for(int i=0;i<count;i++){
    ushort monster=r.ReadUInt16(),rows=r.ReadUInt16();if(monster==0||rows<1||rows>64||Table.ContainsKey(monster))throw new InvalidDataException("Death tower drop record header");
    uint[][] entries=new uint[rows][];
    for(int k=0;k<rows;k++){
     ushort item=r.ReadUInt16(),weight=r.ReadUInt16();
     // Rows keep the PVF's own weights (the same units the floor pools use: the draw is in
     // [0,10000), so `6515 2000` is 20% and `6515 10000` is certain). They are not required to
     // increase - a block may list several rows at the same weight.
     if(item<=2||weight==0||weight>10000)throw new InvalidDataException("Death tower drop row");
     entries[k]=new uint[]{item,weight};
    }
    Table.Add(monster,entries);Records++;Items+=rows;
   }
   if(r.BaseStream.Position!=r.BaseStream.Length)throw new InvalidDataException("Death tower drop catalog trailing bytes");
  }
 }
 internal static bool Has(ushort monster){return Table.ContainsKey(monster);}
 // One cumulative draw in [0,10000): the same shape Floor-Catalog pools use, so `6515 2000` is a
 // 20% chance per kill and `6515 10000` is certain. A monster with no row here drops nothing.
 internal static List<Offline70FloorDropsFG119.Reward> Plan(ushort monster,string receipt){
  List<Offline70FloorDropsFG119.Reward> rewards=new List<Offline70FloorDropsFG119.Reward>();
  uint[][] rows;
  if(!Table.TryGetValue(monster,out rows))return rewards;
  Func<int,int> draw=Offline70QuestDropsFG.StableDraws(receipt+"-tower");
  uint roll=(uint)draw(10000);
  foreach(uint[] row in rows)if(roll<row[1]){rewards.Add(new Offline70FloorDropsFG119.Reward{Item=row[0],Quantity=1,Source="death-tower"});break;}
  return rewards;
 }
}
